package com.bilgiarena.app;
import android.app.*;
import android.content.*;
import android.os.Build;
import java.util.*;
/** Optional device-local reminders. Inexact alarms can be delayed by Android. */
public final class ReminderReceiver extends BroadcastReceiver {
 private static PendingIntent alarm(Context c,int request){return PendingIntent.getBroadcast(c,request,new Intent(c,ReminderReceiver.class).setAction(request==1?"daily":"final"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void clear(Context c){AlarmManager manager=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);manager.cancel(alarm(c,1));manager.cancel(alarm(c,2));c.getSharedPreferences("arena",0).edit().putBoolean("dailyReminder",false).remove("finalReminderAt").apply();}
 static void daily(Context c,boolean enabled){var prefs=c.getSharedPreferences("arena",0);prefs.edit().putBoolean("dailyReminder",enabled).apply();AlarmManager manager=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);manager.cancel(alarm(c,1));if(!enabled)return;Calendar time=Calendar.getInstance(TimeZone.getTimeZone("Europe/Istanbul"));time.set(Calendar.HOUR_OF_DAY,20);time.set(Calendar.MINUTE,0);time.set(Calendar.SECOND,0);time.set(Calendar.MILLISECOND,0);if(time.getTimeInMillis()<=System.currentTimeMillis())time.add(Calendar.DAY_OF_YEAR,1);manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,time.getTimeInMillis(),alarm(c,1));}
 static void finalAt(Context c,long at){if(at<=System.currentTimeMillis())return;c.getSharedPreferences("arena",0).edit().putLong("finalReminderAt",at).apply();((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c,2));}
 @Override public void onReceive(Context c,Intent intent){var prefs=c.getSharedPreferences("arena",0);if(Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())){daily(c,prefs.getBoolean("dailyReminder",false));finalAt(c,prefs.getLong("finalReminderAt",0));return;}boolean daily="daily".equals(intent.getAction());if(!daily&&prefs.getLong("finalReminderAt",0)==0)return;if(daily&&!prefs.getBoolean("dailyReminder",false))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("arena-reminders","Oyun hatırlatmaları",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);manager.notify(daily?1:2,new Notification.Builder(c,"arena-reminders").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(daily?"Günün karma turu seni bekliyor":"Final katılım saati yaklaşıyor").setContentText(daily?"Günlük hedefini uygulamada görebilirsin. Antrenman her zaman açık.":"Odayı aç ve katılım penceresini kontrol et.").setContentIntent(open).setAutoCancel(true).build());if(daily)daily(c,true);else prefs.edit().remove("finalReminderAt").apply();}
}
